// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;

    function setUp() public { c = new MyContract(); }

    function testFuzz_property(address receiver, uint256 amount) public {
        vm.assume(receiver != address(0));
        vm.assume(receiver != address(c));
        amount = bound(amount, 1, 1e18);

        // receiver starts with a balance unrelated to amount
        vm.deal(receiver, 1);
        // c holds enough to cover the transfer
        vm.deal(address(c), amount);

        uint256 before = address(c).balance;
        vm.prank(address(this));
        try c.sendTo(receiver, amount) {
            assertTrue(address(c).balance == before - amount);
        } catch {
            assertTrue(address(c).balance == before);
        }
    }
}
